classdef TransitMapper < OceanViz.Adapters.ISpatialMapper
    % TRANSITMAPPER  Adapter bridging TransitNetwork nodes to spatial coordinates.
    %
    % This class wraps a TransitNetwork (often generated by the interactive
    % TrackDesigner GUI) and implements the ISpatialMapper contract. It allows
    % abstract simulation engines (like Markov Chains) to blindly query spatial
    % coordinates without knowing they are driving on a custom transit map.
    %
    % Usage:
    %   % Load the GUI-designed network
    %   tn = OceanMath.Transit.TransitNetwork();
    %   td = OceanViz.Designer.TrackDesigner();
    %   td.loadDesignStruct_(load('my_custom_map.mat'));
    %   
    %   % Wrap it in the Spatial Mapper Adapter
    %   mapper = OceanViz.Adapters.TransitMapper(td.Transit_);
    %
    %   % Now pass the mapper to the 3D Viz Engine or Markov Simulator!
    %   coords = mapper.mapState(3); % Gets geographic [x, y] of station 3
    %
    % See also: OceanViz.Adapters.ISpatialMapper,
    %           OceanMath.Transit.TransitNetwork

    properties (Access = private)
        Network_  % OceanMath.Transit.TransitNetwork
    end

    methods
        function obj = TransitMapper(transitNetwork)
            % TRANSITMAPPER  Wrap an existing TransitNetwork.
            arguments
                transitNetwork
            end
            obj.Network_ = transitNetwork;
        end

        function coords = mapState(obj, stateIndex)
            % MAPSTATE  Translate abstract station ID to [x, y] coordinates.
            if obj.isValidState(stateIndex)
                coords = obj.Network_.getStation(stateIndex).Position;
            else
                coords = [NaN, NaN];
            end
        end

        function coordSeq = mapSequence(obj, stateSeq)
            % MAPSEQUENCE  Batch-translate a Markov chain trajectory.
            N = numel(stateSeq);
            coordSeq = zeros(N, 2);
            for i = 1:N
                coordSeq(i, :) = obj.mapState(stateSeq(i));
            end
        end

        function D = getDimensions(obj)
            % GETDIMENSIONS  Designer networks are strictly 2-Dimensional.
            D = 2;
        end

        function N = getNumStates(obj)
            % GETNUMSTATES  The total number of stations in the network.
            N = obj.Network_.getStationCount();
        end
    end
end
